    const rotationPercent = ((utcTotalSeconds / 86164.0916) * 100).toFixed(3);

    const message = `*🔄 Rotasi Bumi Saat Ini:*
• Persentase rotasi: _${rotationPercent}%_
• Sudut rotasi: _${((utcTotalSeconds / 86164.0916) * 360).toFixed(2)}°_
• Kecepatan linear: _1.670 km/jam_

_Bumi berotasi penuh setiap 23 jam 56 menit 4.1 detik (periode sideris)_`;

    await reply(message);
  } catch (error) {
    await reply(`*Error:* ${error.message}`);
  }
